+        }
+    }
+
+    private void handleRequest(ChannelHandlerContext ctx, HttpRequest request) {
+        contentExpected = false;
+        if (request.decoderResult().isFailure()) {
+            ctx.fireChannelRead(request);
+            return;
+        }
